package com.fasterxml.jackson.databind.ser.std;

import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.jsonFormatVisitors.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.JsonFormatVisitorWrapper;
import com.fasterxml.jackson.databind.ser.std.NumberSerializer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Type;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class NumberSerializer_acceptJsonFormatVisitor_TriageGen2Test {

    @Mock
    private JsonFormatVisitorWrapper visitor;

    @Mock
    private JavaType typeHint;

    /**
     * Tests the branch where _isInt is true.
     * Since _isInt is a private field, we use a subclass or a specific type 
     * that triggers the _isInt = true state if possible. 
     * In Jackson's NumberSerializer, Integer/Long types typically set _isInt to true.
     */
    @Test
    public void testAcceptJsonFormatVisitor_WhenIsIntIsTrue() throws JsonMappingException {
        // Integer type in Jackson's NumberSerializer typically sets _isInt = true
        NumberSerializer serializer = new NumberSerializer(Integer.class);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // verify visitIntFormat was called via the internal logic
        // visitIntFormat calls visitor.expectIntFormat(typeHint)
        verify(visitor).expectIntFormat(typeHint);
    }

    /**
     * Tests the branch where _isInt is false.
     * Since the code contains a "if (false)" block, we can only cover 
     * the 'else' part of that specific conditional.
     */
    @Test
    public void testAcceptJsonFormatVisitor_WhenIsIntIsFalse() throws JsonMappingException {
        // Double/Float/BigDecimal typically set _isInt = false
        NumberSerializer serializer = new NumberSerializer(Double.class);

        serializer.acceptJsonFormatVisitor(visitor, typeHint);

        // The code executes: visitor.expectNumberFormat(typeHint)
        // because the 'if (false)' block is unreachable.
        verify(visitor).expectNumberFormat(typeHint);
    }

    /**
     * Test to ensure that the method propagates JsonMappingException if the visitor throws it.
     */
    @Test(expected = JsonMappingException.class)
    public void testAcceptJsonFormatVisitor_ThrowsException() throws JsonMappingException {
        NumberSerializer serializer = new NumberSerializer(Integer.class);

        // Simulate an exception during the visitor call
        when(visitor.expectIntFormat(any())).thenThrow(new JsonMappingException(null, "Simulated Error"));

        serializer.acceptJsonFormatVisitor(visitor, typeHint);
    }
}
